uint32_t val = 0xDEADBEEF;
uint8_t *byte_ptr = (uint8_t *)&val;

// Check value stored at lowest memory address (byte_ptr[0])

// Little Endian: LSB stored first
// byte_ptr[0] == 0xEF

// Big Endian: MSB stored first
// byte_ptr[0] == 0xDE

int is_little_endian = (byte_ptr[0] == 0xEF);

